+fn load_flatbuffer_memory(
+    payload: DatFilePayload<'_>,
+) -> Result<VerifiedFlatbufferMemory, DeserializationError> {
+    if payload.crate_version_matches {
+        // Same crate version and a matching SeaHash. Skip `fb::root_as_engine`.
+        // The checksum catches corruption. It does not stop someone who can rewrite the file.
